import unittest
from oracle_observations import observations

class TestOracle(unittest.TestCase):
    def test_e1(self):
        for case_id in ['missing', 'null', 'false', 'true', 'empty_string', 'numeric_string', 'fraction', 'array', 'object']:
            observation = next(o for o in observations if o['id'] == case_id)
            if observation.get('exception'):
                continue
            result = observation['returnValue']
            self.assertIs(result['ok'], False, case_id)
            self.assertTrue(result['reason'], case_id)
        for case_id, expected in [('zero', True), ('one', False)]:
            observation = next(o for o in observations if o['id'] == case_id)
            self.assertFalse(observation.get('exception'), case_id)
            self.assertIs(observation['returnValue']['ok'], expected, case_id)

